package dolt

import (
	"context"
	"sync/atomic"
	"testing"
	"time"

	"github.com/steveyegge/beads/internal/types"
)

// TestCreateIssuesReplayRemintsBatchIdentities (bd-t4h0n7, PR #6754): a
// server batch whose ids, comment ids and default dependency owners were all
// generated by a rolled-back first attempt must regenerate every one of them
// on the replay, owned by the NEW issue identities — a leaked id would write
// the batch's auxiliary rows (comments, dependency edges) under the writer's
// row, changing the winner's auxiliary data.
func TestCreateIssuesReplayRemintsBatchIdentities(t *testing.T) {
	store, cleanup := setupConcurrentTestStore(t)
	defer cleanup()

	ctx, cancel := concurrentTestContext(t)
	defer cancel()

	if err := store.SetConfig(ctx, "issue_id_mode", "counter"); err != nil {
		t.Fatalf("SetConfig(issue_id_mode=counter): %v", err)
	}

	// The dependency target exists ahead of the batch; the edge's owner
	// (dep.IssueID) is left empty so the create defaults it to the owning
	// issue's generated id.
	target := &types.Issue{ID: "test-dep", Title: "dependency target", Status: types.StatusOpen, Priority: 2, IssueType: types.TypeTask}
	if err := store.CreateIssue(ctx, target, "tester"); err != nil {
		t.Fatalf("CreateIssue(target): %v", err)
	}

	firstAttempt := make(chan struct{})
	release := make(chan struct{})
	var attempts atomic.Int32
	store.createAttemptHook = func() {
		if attempts.Add(1) == 1 {
			close(firstAttempt)
			<-release
		}
	}

	first := &types.Issue{
		Title: "batch one", Status: types.StatusOpen, Priority: 2, IssueType: types.TypeTask,
		Comments:     []*types.Comment{{Author: "tester", Text: "first issue comment"}},
		Dependencies: []*types.Dependency{{DependsOnID: "test-dep", Type: types.DepBlocks}},
	}
	second := &types.Issue{Title: "batch two", Status: types.StatusOpen, Priority: 2, IssueType: types.TypeTask}
	errCh := make(chan error, 1)
	go func() {
		errCh <- store.CreateIssues(ctx, []*types.Issue{first, second}, "tester")
	}()

	settle := func() {
		select {
		case <-release:
		default:
			close(release)
		}
		select {
		case <-errCh:
		case <-time.After(60 * time.Second):
		}
	}

	<-firstAttempt
	minted := first.ID
	if minted == "" {
		settle()
		t.Fatal("first attempt minted no id for the first batch item before the hook fired")
	}

	// The winner: a row under the first item's minted id plus its created
	// event, committed while the batch's first attempt sits uncommitted.
	if _, err := store.db.ExecContext(ctx,
		"INSERT INTO issues (id, title, description, design, acceptance_criteria, notes) VALUES (?, ?, ?, '', '', '')",
		minted, "conflicting writer", "writer row"); err != nil {
		settle()
		t.Fatalf("writer insert: %v", err)
	}
	if _, err := store.db.ExecContext(ctx,
		"INSERT INTO events (id, issue_id, event_type, actor) VALUES (UUID(), ?, 'created', 'writer')", minted); err != nil {
		settle()
		t.Fatalf("writer event: %v", err)
	}

	close(release) // the batch's first attempt commits into the conflict and replays

	err := <-errCh
	if err != nil {
		t.Fatalf("CreateIssues after replay: %v", err)
	}

	// New, distinct identities: re-minted past the winner, in batch order.
	if first.ID == minted || first.ID == "" {
		t.Fatalf("replayed batch kept the rolled-back identity %q for its first item; it must re-mint distinctly", first.ID)
	}
	if first.ID != "test-2" || second.ID != "test-3" {
		t.Fatalf("replayed batch ids = (%q, %q), want (test-2, test-3) past the writer's %q", first.ID, second.ID, minted)
	}

	// The winner's row and auxiliary data are unchanged: its content, its one
	// created event, and no comment or dependency edge the batch tried to put
	// under it.
	winner, err := store.GetIssue(ctx, minted)
	if err != nil {
		t.Fatalf("GetIssue(winner %s): %v", minted, err)
	}
	if winner.Title != "conflicting writer" {
		t.Errorf("winner row title = %q, want %q", winner.Title, "conflicting writer")
	}
	assertCount(t, ctx, store, "SELECT COUNT(*) FROM events WHERE issue_id = ? AND event_type = 'created'", []any{minted}, 1, "winner created events")
	assertCount(t, ctx, store, "SELECT COUNT(*) FROM comments WHERE issue_id = ?", []any{minted}, 0, "winner comments")
	assertCount(t, ctx, store, "SELECT COUNT(*) FROM dependencies WHERE issue_id = ?", []any{minted}, 0, "winner dependency edges")

	// The regenerated identities own their auxiliary rows: the comment and
	// the default-owned edge point at the new first id, not the rolled-back
	// one.
	assertCount(t, ctx, store, "SELECT COUNT(*) FROM comments WHERE issue_id = ?", []any{first.ID}, 1, "first item comments")
	assertCount(t, ctx, store, "SELECT COUNT(*) FROM dependencies WHERE issue_id = ? AND depends_on_issue_id = 'test-dep'", []any{first.ID}, 1, "first item dependency edge")
	assertCount(t, ctx, store, "SELECT COUNT(*) FROM events WHERE issue_id = ? AND event_type = 'created'", []any{first.ID}, 1, "first item created events")
	assertCount(t, ctx, store, "SELECT COUNT(*) FROM events WHERE issue_id = ? AND event_type = 'created'", []any{second.ID}, 1, "second item created events")
}

func assertCount(t *testing.T, ctx context.Context, store *DoltStore, query string, args []any, want int, what string) {
	t.Helper()
	var got int
	if err := store.db.QueryRowContext(ctx, query, args...).Scan(&got); err != nil {
		t.Fatalf("count %s: %v", what, err)
	}
	if got != want {
		t.Errorf("%s = %d, want %d", what, got, want)
	}
}
